import{a as p}from"./chunk-XVHDQB6S.js";import{a as g}from"./chunk-BF5NZG73.js";import"./chunk-TRYNAU5S.js";import"./chunk-5II3MPMJ.js";import{a as h}from"./chunk-ASS7GFNI.js";import{a}from"./chunk-C7PGRU37.js";import"./chunk-2MU6OKRB.js";import{X as b}from"./chunk-K3IKQ6MG.js";import{Ra as l,ta as i,ub as r,xa as d}from"./chunk-RIQZW2OE.js";import{a as t,b as c,h as T}from"./chunk-TWZW5B45.js";var f=T(b());var y={category:h,title:"Theming",mdFile:"./index.md",order:p("theming")},n=y;var m=[];var w={},u=w;var v=`<p class="ngde">The <code class="ngde">@angularity/theming</code> package offers a programmatic runtime theming system that allows dynamic theming at the runtime or based on remote configurations.</p><pre class="shiki shiki-themes github-light ayu-dark" style="background-color:#fff;--shiki-dark-bg:#0b0e14;color:#24292e;--shiki-dark:#bfbdb6" tabindex="0"><code class="language-sh"><span class="line"><span style="color:#6F42C1;--shiki-dark:#59C2FF" class="ngde">npm</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> i</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> @angularity/{core,theming}</span></span></code></pre><h3 id="exported-from-angularitytheming" href="packages/theming" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/theming</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularitytheming"></ng-doc-heading-anchor></h3><p class="ngde">Top-level:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/theming/provideTheme" class="ng-doc-code-anchor ngde">provideTheme</a></code><p class="ngde">Make providers that consume the given theme.</p><p class="ngde">The application initialization process will be blocked until the the initial theme tokens are available. The initial theme tokens might be the pre-built tokens from the server (SSR environment), or be built from scratch if no server tokens exist.</p><p class="ngde">For CSR applications, async theme is discouraged, since it slows down application bootstrap. For SSR applications, using async theme can help reduce the size of the initial bundle as well as accelerate bootstrap, because the theme is pre-built on server and immediately available on browser.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/theming/createTheme" class="ng-doc-code-anchor ngde">createTheme</a></code><p class="ngde">Create a <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/theming/Theme" class="ng-doc-code-anchor ngde">Theme</a></code> object from a list of <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/theming/TokenBuild" class="ng-doc-code-anchor ngde">TokenBuild</a></code> specifications.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/theming/scheduleTokenBuild" class="ng-doc-code-anchor ngde">scheduleTokenBuild</a></code><p class="ngde">Creates a token generation specification, which specifies the target <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/theming/TokenBuilder" class="ng-doc-code-anchor ngde">TokenBuilder</a></code> and relevant configurations to be passed to the builder.</p></li></ul><p class="ngde">Fundamentals:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/interfaces/theming/TokenBuilder" class="ng-doc-code-anchor ngde">TokenBuilder</a></code><p class="ngde">Responsible for generating a group of theme tokens based on a configuration.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/ThemeTokenRegistry" class="ng-doc-code-anchor ngde">ThemeTokenRegistry</a></code><p class="ngde">Registry for active theme tokens in the current application.</p><p class="ngde">On server, the tokens will be written to <code class="ngde ng-doc-code-with-link"><a href="https://angular.dev/api/core/TransferState" class="ng-doc-code-anchor ngde" ngDocTooltip="External link the Angular documentation.">TransferState</a></code>, and can be later reused on browser via the <code class="ngde">transfer</code> method.</p></li></ul><p class="ngde">Implementations:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/VanillaBuilder" class="ng-doc-code-anchor ngde">VanillaBuilder</a></code><p class="ngde">An implementation of <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/theming/TokenBuilder" class="ng-doc-code-anchor ngde">TokenBuilder</a></code> that simply accepts an object of pre-defined theme tokens as configuration and returns them as is when requested to generate tokens.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/InMemoryThemeTokenRegistry" class="ng-doc-code-anchor ngde">InMemoryThemeTokenRegistry</a></code><p class="ngde">Implementation of <code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/ThemeTokenRegistry" class="ng-doc-code-anchor ngde">ThemeTokenRegistry</a></code> that stores theme tokens in memory.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/WriteTokensToRootCssVariables" class="ng-doc-code-anchor ngde">WriteTokensToRootCssVariables</a></code><p class="ngde">Decorator of <code class="ngde ng-doc-code-with-link"><a href="api/classes/theming/ThemeTokenRegistry" class="ng-doc-code-anchor ngde">ThemeTokenRegistry</a></code> that writes theme tokens to the root element as CSS variables.</p><ul class="ngde"><li class="ngde">On server, the tokens will be written to the root element's style properties as CSS variables.</li><li class="ngde">On modern browser, the tokens will be written to a constructed <code class="ngde">CSSStyleSheet</code> object adopted by the document.</li><li class="ngde">On legacy browser, the tokens will be written to a <code class="ngde ng-doc-code-with-link">&#x3C;<a href="https://angular.dev/api/animations/style" class="ng-doc-code-anchor ngde" ngDocTooltip="External link the Angular documentation.">style</a>></code> element appended to the document head.</li></ul></li></ul>`,R=(()=>{let e=class e extends a{constructor(){super(),this.pageType="guide",this.pageContent=v,this.page=n,this.demoAssets=u}};e.\u0275fac=function(s){return new(s||e)},e.\u0275cmp=i({type:e,selectors:[["ng-doc-page-69cjsp7e"]],features:[r([{provide:a,useExisting:e},m,n.providers??[]]),d],decls:1,vars:0,template:function(s,x){s&1&&l(0,"ng-doc-page")},dependencies:[g],encapsulation:2,changeDetection:0});let o=e;return o})(),C=[c(t({},(0,f.isRoute)(n.route)?n.route:{}),{path:"",component:R,title:"Theming"})],V=C;export{R as PageComponent,V as default};
